"use client";

import { useEffect, useMemo, useState } from "react";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import {
  ArrowDown, ArrowUp, ChevronDown, ChevronLeft, ChevronRight, CircleHelp,
  Database, Eye, FileSpreadsheet, Pencil, Plus, Search,
  SlidersHorizontal, Trash2, Upload, X,
} from "lucide-react";
import { formatDate, formatNumber, withLocale, type Locale } from "@/lib/i18n";
import { sampleCatalogId, sampleWorkspaceId } from "@/lib/sample-catalog";
import "./catalog-workspace.css";

type FieldType = "string" | "number" | "boolean" | "time" | "geo" | "object" | "array";
type CatalogField = { name: string; type: FieldType };
type CatalogSettings = {
  backInStock: boolean; priceDrop: boolean; subscriptionEvent: string; unsubscribeEvent: string;
  itemIdProperty: string; inventoryField: string; priceField: string; notifyMode: "all" | "rate"; rate: number;
};
type Catalog = {
  id: string; name: string; description: string; status: string; updatedAt: string; itemCount: number;
  data: { fields?: string[]; fieldTypes?: Record<string, FieldType>; source?: string; size?: string; sample?: boolean; settings?: CatalogSettings };
};
type Item = { id: string; name: string; fields: Record<string, unknown>; updatedAt: string };
type FilterOperator = "equals" | "not_equals" | "contains" | "not_contains" | "greater_than" | "less_than" | "exists" | "not_exists";
type Selection = {
  catalogId: string; name: string; description: string;
  filters: Array<{ field: string; operator: FilterOperator; value: string }>;
  randomSort: boolean; sortField: string; sortDirection: "ascending" | "descending"; resultLimit: number; updatedAt: string;
};
type LocalCatalogRecord = { catalog: Catalog; items: Item[]; selections: Selection[]; settings: CatalogSettings };
type Recommendation = { id: string; name: string; description: string; data: { catalogId?: string; selectionName?: string; recommendationType?: string; trackingType?: string; propertyName?: string } };
type LocalWorkspace = { version: 1; records: Record<string, LocalCatalogRecord> };
type Section = "Preview" | "Selections" | "Settings";
type Dialog =
  | { kind: "create"; method?: "browser" | "csv" }
  | { kind: "fields" }
  | { kind: "item"; item?: Item }
  | { kind: "csv" }
  | { kind: "selection"; selection?: Selection }
  | { kind: "deleteCatalog" }
  | null;

const STORAGE_KEY = "braze.catalog.workspace.v2";
const fieldTypes: Array<{ value: FieldType; label: string }> = [
  { value: "string", label: "String" }, { value: "number", label: "Number" },
  { value: "boolean", label: "Boolean" }, { value: "time", label: "Time" },
  { value: "geo", label: "Geolocation" }, { value: "object", label: "JSON object" },
  { value: "array", label: "String array" },
];
const emptySettings: CatalogSettings = {
  backInStock: false, priceDrop: false, subscriptionEvent: "", unsubscribeEvent: "",
  itemIdProperty: "id", inventoryField: "", priceField: "", notifyMode: "all", rate: 100,
};
const listUrl = (locale: Locale) => withLocale(`/dashboard/catalogs/${sampleWorkspaceId}`, locale);
const detailUrl = (locale: Locale, id: string, name: string, tab?: Section) => withLocale(`/dashboard/catalogs/${encodeURIComponent(id)}/${sampleWorkspaceId}?name=${encodeURIComponent(name)}${tab ? `&tab=${tab.toLowerCase()}` : ""}`, locale);
const selectionUrl = (locale: Locale, catalogId: string, name: string) => withLocale(`/dashboard/catalogs/${catalogId}/selection/${encodeURIComponent(name)}/${sampleWorkspaceId}`, locale);
const now = () => new Date().toISOString();
const uid = (prefix: string) => `${prefix}_${crypto.randomUUID().replaceAll("-", "").slice(0, 16)}`;
const display = (value: unknown) => value == null || value === "" ? "—" : typeof value === "object" ? JSON.stringify(value) : String(value);
const date = (locale: Locale, value: string) => formatDate(locale, value, { year: "numeric", month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });

function loadLocal(): LocalWorkspace {
  if (typeof window === "undefined") return { version: 1, records: {} };
  try {
    const parsed = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? "") as LocalWorkspace;
    return parsed?.version === 1 && parsed.records ? parsed : { version: 1, records: {} };
  } catch { return { version: 1, records: {} }; }
}

function inferType(values: string[]): FieldType {
  const present = values.filter(Boolean);
  if (present.length && present.every(value => /^(true|false)$/i.test(value))) return "boolean";
  if (present.length && present.every(value => Number.isFinite(Number(value)))) return "number";
  if (present.length && present.every(value => /^\d{4}-\d{2}-\d{2}(?:T|$)/.test(value))) return "time";
  return "string";
}

function parseCsv(text: string) {
  const rows: string[][] = []; let row: string[] = []; let cell = ""; let quoted = false;
  for (let index = 0; index < text.length; index += 1) {
    const character = text[index];
    if (character === '"' && quoted && text[index + 1] === '"') { cell += '"'; index += 1; }
    else if (character === '"') quoted = !quoted;
    else if (character === "," && !quoted) { row.push(cell); cell = ""; }
    else if ((character === "\n" || character === "\r") && !quoted) {
      if (character === "\r" && text[index + 1] === "\n") index += 1;
      row.push(cell); if (row.some(value => value.length)) rows.push(row); row = []; cell = "";
    } else cell += character;
  }
  row.push(cell); if (row.some(value => value.length)) rows.push(row);
  const headers = (rows.shift() ?? []).map(value => value.trim());
  return { headers, rows: rows.map(values => Object.fromEntries(headers.map((header, index) => [header, values[index] ?? ""]))) };
}

function coerce(value: string, type: FieldType): unknown {
  if (value === "") return "";
  if (type === "number") return Number(value);
  if (type === "boolean") return value.toLowerCase() === "true";
  if (type === "object" || type === "array" || type === "geo") { try { return JSON.parse(value); } catch { return value; } }
  return value;
}

function matches(item: Item, filter: Selection["filters"][number]) {
  const raw = filter.field === "id" ? item.id : item.fields[filter.field];
  const left = String(raw ?? "").toLowerCase(); const right = filter.value.toLowerCase();
  if (filter.operator === "not_equals") return left !== right;
  if (filter.operator === "contains") return left.includes(right);
  if (filter.operator === "not_contains") return !left.includes(right);
  if (filter.operator === "greater_than") return Number(raw) > Number(filter.value);
  if (filter.operator === "less_than") return Number(raw) < Number(filter.value);
  if (filter.operator === "exists") return raw != null && raw !== "";
  if (filter.operator === "not_exists") return raw == null || raw === "";
  return left === right;
}

export default function CatalogStudio({ locale, notify }: { locale: Locale; notify: (message: string) => void }) {
  const router = useRouter(); const pathname = usePathname(); const searchParams = useSearchParams();
  const selectionRoute = pathname.match(/^\/dashboard\/catalogs\/([^/]+)\/selection\/([^/]+)\/([^/]+)$/);
  const selectedId = selectionRoute?.[1] ?? pathname.match(/^\/dashboard\/catalogs\/([^/]+)\/([^/]+)$/)?.[1] ?? null;
  const [remoteCatalogs, setRemoteCatalogs] = useState<Catalog[]>([]);
  const [local, setLocal] = useState<LocalWorkspace>({ version: 1, records: {} });
  const [remoteItems, setRemoteItems] = useState<Record<string, Item[]>>({});
  const [remoteSelections, setRemoteSelections] = useState<Record<string, Selection[]>>({});
  const [loading, setLoading] = useState(true); const [dialog, setDialog] = useState<Dialog>(null);

  useEffect(() => { setLocal(loadLocal()); void fetch("/api/catalogs").then(response => response.ok ? response.json() : { data: [] }).then(result => { setRemoteCatalogs(result.data.filter((catalog: Catalog) => catalog.id !== "catalog_featured")); setLoading(false); }); }, []);
  useEffect(() => { if (!selectedId || local.records[selectedId]) return; void Promise.all([fetch(`/api/catalogs/${selectedId}/items`), fetch(`/api/catalogs/${selectedId}/selections`)]).then(async ([itemsResponse, selectionsResponse]) => {
    const loadedItems = itemsResponse.ok ? (await itemsResponse.json()).data as Item[] : null;
    const loadedSelections = selectionsResponse.ok ? (await selectionsResponse.json()).data as Selection[] : null;
    if (loadedItems) setRemoteItems(current => ({ ...current, [selectedId]: loadedItems }));
    if (loadedSelections) setRemoteSelections(current => ({ ...current, [selectedId]: loadedSelections }));
  }); }, [selectedId, local.records]);

  function saveLocal(updater: (workspace: LocalWorkspace) => LocalWorkspace) {
    setLocal(current => { const next = updater(current); localStorage.setItem(STORAGE_KEY, JSON.stringify(next)); return next; });
  }
  const catalogs = useMemo(() => {
    const map = new Map(remoteCatalogs.map(catalog => [catalog.name.toLowerCase(), catalog]));
    Object.values(local.records).forEach(record => map.set(record.catalog.name.toLowerCase(), { ...record.catalog, itemCount: record.items.length }));
    return [...map.values()];
  }, [local, remoteCatalogs]);
  const selected = catalogs.find(catalog => catalog.id === selectedId) ?? null;
  const items = selectedId && local.records[selectedId] ? local.records[selectedId].items : selectedId ? remoteItems[selectedId] ?? [] : [];
  const selections = selectedId && local.records[selectedId] ? local.records[selectedId].selections : selectedId ? remoteSelections[selectedId] ?? [] : [];
  const settings = selectedId && local.records[selectedId]?.settings ? local.records[selectedId].settings : selected?.data.settings ?? emptySettings;
  const editable = Boolean(selected && !selected.data.sample);

  function updateRecord(id: string, update: (record: LocalCatalogRecord) => LocalCatalogRecord) {
    saveLocal(workspace => ({ ...workspace, records: { ...workspace.records, [id]: update(workspace.records[id]) } }));
  }
  async function mirror(url: string, init: RequestInit) { try { await fetch(url, init); } catch { /* Browser storage remains authoritative for the demo. */ } }

  if (selectionRoute && selected) {
    const name = decodeURIComponent(selectionRoute[2]); const selection = selections.find(value => value.name === name);
    return <SelectionView locale={locale} catalog={selected} selection={selection} items={items} editable={editable} loading={loading && !selection} onBack={() => router.push(detailUrl(locale, selected.id, selected.name, "Selections"))} onEdit={() => selection && setDialog({ kind: "selection", selection })} dialog={dialog} closeDialog={() => setDialog(null)} saveSelection={(next, originalName) => {
      updateRecord(selected.id, record => ({ ...record, selections: [...record.selections.filter(value => value.name !== originalName), next] }));
      void mirror(`/api/catalogs/${selected.id}/selections/${encodeURIComponent(originalName)}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(next) });
      setDialog(null); router.push(selectionUrl(locale, selected.id, next.name)); notify("Selection saved.");
    }}/>;
  }

  return <CatalogWorkspaceView locale={locale} catalogs={catalogs} selected={selected} items={items} selections={selections} settings={settings} editable={editable} loading={loading} dialog={dialog} setDialog={setDialog} notify={notify} navigate={url => router.push(url)} saveLocal={saveLocal} updateRecord={updateRecord} mirror={mirror}/>;
}

function CatalogWorkspaceView({ locale, catalogs, selected, items, selections, settings, editable, loading, dialog, setDialog, notify, navigate, saveLocal, updateRecord, mirror }: {
  locale: Locale; catalogs: Catalog[]; selected: Catalog | null; items: Item[]; selections: Selection[]; settings: CatalogSettings; editable: boolean; loading: boolean;
  dialog: Dialog; setDialog: (dialog: Dialog) => void; notify: (message: string) => void; navigate: (url: string) => void;
  saveLocal: (updater: (workspace: LocalWorkspace) => LocalWorkspace) => void;
  updateRecord: (id: string, update: (record: LocalCatalogRecord) => LocalCatalogRecord) => void;
  mirror: (url: string, init: RequestInit) => Promise<void>;
}) {
  const searchParams = useSearchParams(); const section = searchParams.get("tab") === "selections" ? "Selections" : searchParams.get("tab") === "settings" ? "Settings" : "Preview";
  const [queryDraft, setQueryDraft] = useState(""); const [query, setQuery] = useState(""); const [filterOpen, setFilterOpen] = useState(false);
  const [filter, setFilter] = useState<{ field: string; operator: FilterOperator; value: string } | null>(null); const [page, setPage] = useState(0); const [limit, setLimit] = useState(12);
  const [sort, setSort] = useState<"items" | "updated">("updated"); const [direction, setDirection] = useState(-1); const [menuOpen, setMenuOpen] = useState(false);
  const [selectedItem, setSelectedItem] = useState<Item | null>(null);
  const fields: CatalogField[] = selected ? (selected.data.fields ?? []).map(name => ({ name, type: selected.data.fieldTypes?.[name] ?? "string" })) : [];
  const visibleCatalogs = useMemo(() => catalogs.filter(catalog => catalog.name.toLowerCase().includes(query.toLowerCase())).sort((left, right) => (sort === "items" ? left.itemCount - right.itemCount : left.updatedAt.localeCompare(right.updatedAt)) * direction), [catalogs, direction, query, sort]);
  const visibleItems = useMemo(() => items.filter(item => (!query || item.id.toLowerCase().includes(query.toLowerCase())) && (!filter || matches(item, filter))), [filter, items, query]);
  const pages = Math.max(1, Math.ceil((selected ? visibleItems.length : visibleCatalogs.length) / limit)); const start = Math.min(page, pages - 1) * limit;

  function removeCatalog() {
    if (!selected) return;
    saveLocal(workspace => { const records = { ...workspace.records }; delete records[selected.id]; return { ...workspace, records }; });
    void mirror(`/api/catalogs/${selected.id}`, { method: "DELETE" }); setDialog(null); navigate(listUrl(locale)); notify("Catalog deleted.");
  }
  function saveItem(item: Item, originalId?: string) {
    if (!selected) return;
    updateRecord(selected.id, record => ({ ...record, items: [...record.items.filter(value => value.id !== (originalId ?? item.id)), item], catalog: { ...record.catalog, itemCount: originalId && originalId !== item.id ? record.items.length : Math.max(record.items.length, record.items.some(value => value.id === item.id) ? record.items.length : record.items.length + 1), updatedAt: now() } }));
    void mirror(`/api/catalogs/${selected.id}/items${originalId ? `/${encodeURIComponent(originalId)}` : ""}`, { method: originalId ? "PATCH" : "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ...item, name: String(item.fields.name ?? item.name ?? item.id) }) });
    setDialog(null); setSelectedItem(null); notify(originalId ? "Item updated." : "Item added.");
  }
  function deleteItem(item: Item) {
    if (!selected) return; updateRecord(selected.id, record => ({ ...record, items: record.items.filter(value => value.id !== item.id), catalog: { ...record.catalog, itemCount: Math.max(0, record.items.length - 1), updatedAt: now() } }));
    void mirror(`/api/catalogs/${selected.id}/items/${encodeURIComponent(item.id)}`, { method: "DELETE" }); setSelectedItem(null); notify("Item deleted.");
  }
  async function beginRecommendation() {
    const response = await fetch("/api/recommendations", { method: "POST" });
    if (!response.ok) { notify("Could not create recommendation."); return; }
    const created = await response.json() as { id: string };
    navigate(withLocale(`/engagement/predictions/${created.id}/${sampleWorkspaceId}`, locale));
  }
  function saveSelection(selection: Selection, originalName?: string) {
    if (!selected) return;
    updateRecord(selected.id, record => ({ ...record, selections: [...record.selections.filter(value => value.name !== (originalName ?? selection.name)), selection] }));
    void mirror(`/api/catalogs/${selected.id}/selections${originalName ? `/${encodeURIComponent(originalName)}` : ""}`, { method: originalName ? "PATCH" : "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(selection) });
    setDialog(null); notify(originalName ? "Selection updated." : "Selection created.");
  }

  if (!selected) return <div className="braze-catalog"><Tabs locale={locale}/><main className="catalog-main catalog-index"><header className="catalog-heading"><div><h1>Catalogs</h1><p>Manage non-user data for personalized messages.</p></div><div className="catalog-heading-actions"><button className="secondary"><Upload size={15}/> Export</button><button className="primary" onClick={() => setDialog({ kind: "create" })}><Plus size={16}/> Create New Catalog</button></div></header><SearchBox value={queryDraft} setValue={setQueryDraft} placeholder="Search for catalogs" onSearch={() => { setQuery(queryDraft.trim()); setPage(0); }}/><p className="catalog-result-count">{formatNumber(locale, visibleCatalogs.length)} Results</p>{loading ? <p>Loading catalogs…</p> : <CatalogTable locale={locale} catalogs={visibleCatalogs.slice(start, start + limit)} sort={sort} direction={direction} setSort={value => { setSort(value); setDirection(sort === value ? direction * -1 : -1); }} open={catalog => navigate(detailUrl(locale, catalog.id, catalog.name))}/>}<Pagination locale={locale} start={visibleCatalogs.length ? start + 1 : 0} end={Math.min(start + limit, visibleCatalogs.length)} total={visibleCatalogs.length} limit={limit} page={page} pages={pages} setPage={setPage} setLimit={setLimit}/><Usage catalogs={catalogs}/><Footer/></main>{dialog?.kind === "create" && <CreateCatalogDialog locale={locale} existingNames={catalogs.map(catalog => catalog.name)} method={dialog.method} setMethod={method => setDialog({ kind: "create", method })} close={() => setDialog(null)} create={(catalog, createdItems, catalogFields) => {
    const settings = { ...emptySettings }; const record = { catalog: { ...catalog, data: { ...catalog.data, fields: catalogFields.map(field => field.name), fieldTypes: Object.fromEntries(catalogFields.map(field => [field.name, field.type])), settings } }, items: createdItems, selections: [], settings };
    saveLocal(workspace => ({ ...workspace, records: { ...workspace.records, [catalog.id]: record } }));
    void (async () => {
      await mirror("/api/catalogs", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(record) });
      await Promise.all(createdItems.map(item => mirror(`/api/catalogs/${catalog.id}/items`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(item) })));
    })(); setDialog(null); navigate(detailUrl(locale, catalog.id, catalog.name)); notify("Catalog created.");
  }}/>}</div>;

  return <div className="braze-catalog"><Tabs locale={locale} selected={selected} navigate={navigate}/><nav className="catalog-section-tabs">{(["Preview", "Selections", "Settings"] as const).map(tab => <button key={tab} className={section === tab ? "selected" : ""} onClick={() => navigate(detailUrl(locale, selected.id, selected.name, tab))}>{tab}</button>)}</nav><main className="catalog-main">{section === "Preview" && <><header className="catalog-heading catalog-detail-heading"><div><h1>{selected.name}{!editable && <ViewOnly/>}</h1><p>{selected.description}</p></div><div className="catalog-heading-actions"><button className="catalog-outline" onClick={() => void beginRecommendation()}>Create recommendation</button>{editable && <div className="catalog-action-menu"><button className="primary" onClick={() => setMenuOpen(!menuOpen)}>Update Catalog <ChevronDown size={15}/></button>{menuOpen && <div className="catalog-menu"><button onClick={() => { setDialog({ kind: "fields" }); setMenuOpen(false); }}><Plus/> Add fields</button><button onClick={() => { setDialog({ kind: "item" }); setMenuOpen(false); }}><Plus/> Add item</button><button onClick={() => { setDialog({ kind: "csv" }); setMenuOpen(false); }}><Upload/> Upload CSV</button><button className="danger" onClick={() => { setDialog({ kind: "deleteCatalog" }); setMenuOpen(false); }}><Trash2/> Delete catalog</button></div>}</div>}</div></header><div className="catalog-preview-tools"><div className="catalog-filter-wrap"><button className="catalog-outline" onClick={() => setFilterOpen(!filterOpen)}><SlidersHorizontal size={16}/> Filters{filter && <span className="filter-count">1</span>}</button>{filterOpen && <FilterPopover fields={[{ name: "id", type: "string" }, ...fields]} apply={value => { setFilter(value); setFilterOpen(false); }} clear={() => { setFilter(null); setFilterOpen(false); }}/>}</div><SearchBox value={queryDraft} setValue={setQueryDraft} placeholder="Search for an item by ID" onSearch={() => { setQuery(queryDraft.trim()); setPage(0); }}/></div><p className="catalog-result-count">{formatNumber(locale, visibleItems.length)} Results</p><ItemsTable fields={fields} items={visibleItems.slice(start, start + limit)} open={setSelectedItem} editable={editable} edit={item => setDialog({ kind: "item", item })}/><Pagination locale={locale} start={visibleItems.length ? start + 1 : 0} end={Math.min(start + limit, visibleItems.length)} total={visibleItems.length} limit={limit} page={page} pages={pages} setPage={setPage} setLimit={setLimit}/></>}{section === "Selections" && <><header className="catalog-heading"><div><small>{selected.name}</small><h1>Selections{!editable && <ViewOnly/>}</h1></div>{editable && <button className="primary" onClick={() => setDialog({ kind: "selection" })}><Plus size={16}/> Create Selection</button>}</header><SearchBox value={queryDraft} setValue={setQueryDraft} placeholder="Search by selection name" onSearch={() => setQuery(queryDraft.trim())}/><p className="catalog-result-count">{selections.filter(value => value.name.toLowerCase().includes(query.toLowerCase())).length} Results</p><SelectionsTable locale={locale} selections={selections.filter(value => value.name.toLowerCase().includes(query.toLowerCase()))} open={selection => navigate(selectionUrl(locale, selected.id, selection.name))} editable={editable} edit={selection => setDialog({ kind: "selection", selection })} remove={selection => { updateRecord(selected.id, record => ({ ...record, selections: record.selections.filter(value => value.name !== selection.name) })); void mirror(`/api/catalogs/${selected.id}/selections/${encodeURIComponent(selection.name)}`, { method: "DELETE" }); notify("Selection deleted."); }}/></>}{section === "Settings" && <SettingsPanel settings={settings} fields={fields} editable={editable} save={next => { updateRecord(selected.id, record => ({ ...record, settings: next, catalog: { ...record.catalog, data: { ...record.catalog.data, settings: next }, updatedAt: now() } })); void mirror(`/api/catalogs/${selected.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ data: { ...selected.data, settings: next } }) }); notify("Catalog settings saved."); }}/>}</main>{selectedItem && <ItemDrawer item={selectedItem} fields={fields} editable={editable} close={() => setSelectedItem(null)} edit={() => setDialog({ kind: "item", item: selectedItem })} remove={() => deleteItem(selectedItem)}/>} {dialog?.kind === "fields" && <FieldsDialog existing={fields} close={() => setDialog(null)} save={added => { const next = [...fields, ...added]; updateRecord(selected.id, record => ({ ...record, catalog: { ...record.catalog, data: { ...record.catalog.data, fields: next.map(field => field.name), fieldTypes: Object.fromEntries(next.map(field => [field.name, field.type])) }, updatedAt: now() }, items: record.items.map(item => ({ ...item, fields: { ...Object.fromEntries(added.map(field => [field.name, ""])), ...item.fields } })) })); setDialog(null); notify("Fields added."); }}/>} {dialog?.kind === "item" && <ItemDialog fields={fields} item={dialog.item} close={() => setDialog(null)} save={saveItem}/>} {dialog?.kind === "selection" && <SelectionDialog catalogId={selected.id} fields={[{ name: "id", type: "string" }, ...fields]} initial={dialog.selection} close={() => setDialog(null)} save={saveSelection}/>} {dialog?.kind === "csv" && <CsvUpdateDialog fields={fields} items={items} close={() => setDialog(null)} apply={(mode, parsedItems) => { updateRecord(selected.id, record => { const incoming = new Map(parsedItems.map(item => [item.id, item])); const nextItems = mode === "delete" ? record.items.filter(item => !incoming.has(item.id)) : mode === "replace" ? parsedItems : [...record.items.filter(item => !incoming.has(item.id)), ...parsedItems]; return { ...record, items: nextItems, catalog: { ...record.catalog, itemCount: nextItems.length, updatedAt: now() } }; }); setDialog(null); notify("CSV processed."); }}/>} {dialog?.kind === "deleteCatalog" && <ConfirmDialog title="Delete catalog?" body={`Permanently delete ${selected.name} and all of its items and selections.`} confirmLabel="Delete catalog" close={() => setDialog(null)} confirm={removeCatalog}/>}</div>;
}

function Tabs({ locale, selected, navigate }: { locale: Locale; selected?: Catalog; navigate?: (url: string) => void }) { return <nav className="catalog-workspace-tabs"><button className={!selected ? "selected" : ""} onClick={() => navigate?.(listUrl(locale))}>Catalogs</button>{selected && <button className="selected">{selected.name}<X size={14} onClick={() => navigate?.(listUrl(locale))}/></button>}</nav>; }
function ViewOnly() { return <span className="catalog-view-pill"><Eye size={13}/> View only</span>; }
function SearchBox({ value, setValue, placeholder, onSearch }: { value: string; setValue: (value: string) => void; placeholder: string; onSearch: () => void }) { return <div className="catalog-search-control"><label><Search size={16}/><input value={value} placeholder={placeholder} onChange={event => setValue(event.target.value)} onKeyDown={event => event.key === "Enter" && onSearch()}/></label><button className="primary" disabled={!value.trim()} onClick={onSearch}>Search</button></div>; }
function CatalogTable({ locale, catalogs, sort, direction, setSort, open }: { locale: Locale; catalogs: Catalog[]; sort: "items" | "updated"; direction: number; setSort: (sort: "items" | "updated") => void; open: (catalog: Catalog) => void }) { return <div className="catalog-scroll"><table className="catalog-grid"><thead><tr><th>Name</th><th>Description</th><th>Source</th><SortHead label="Items" active={sort === "items"} direction={direction} click={() => setSort("items")}/><th>Total size</th><SortHead label="Last updated" active={sort === "updated"} direction={direction} click={() => setSort("updated")}/><th><CircleHelp size={14}/></th></tr></thead><tbody>{catalogs.map(catalog => <tr key={catalog.id}><td><button className="catalog-link" onClick={() => open(catalog)}>{catalog.name}</button></td><td>{catalog.description}</td><td>{catalog.data.source ?? "Braze"}</td><td>{catalog.itemCount}</td><td>{catalog.data.size ?? "—"}</td><td>{date(locale, catalog.updatedAt)}</td><td/></tr>)}</tbody></table></div>; }
function SortHead({ label, active, direction, click }: { label: string; active: boolean; direction: number; click: () => void }) { return <th><button className="catalog-sort" onClick={click}>{label}{active && (direction < 0 ? <ArrowDown size={13}/> : <ArrowUp size={13}/>)}</button></th>; }
function Pagination({ locale, start, end, total, limit, page, pages, setPage, setLimit }: { locale: Locale; start: number; end: number; total: number; limit: number; page: number; pages: number; setPage: (page: number) => void; setLimit: (limit: number) => void }) { return <footer className="catalog-pagination"><span>Showing rows {formatNumber(locale, start)}-{formatNumber(locale, end)} of {formatNumber(locale, total)}</span><label>Rows per page <select value={limit} onChange={event => { setLimit(Number(event.target.value)); setPage(0); }}><option>12</option><option>24</option><option>48</option></select></label><div><button disabled={!page} onClick={() => setPage(page - 1)}><ChevronLeft size={17}/></button><span>{page + 1}</span><button disabled={page >= pages - 1} onClick={() => setPage(page + 1)}><ChevronRight size={17}/></button></div></footer>; }
function Usage({ catalogs }: { catalogs: Catalog[] }) { const bytes = catalogs.reduce((total, catalog) => total + Number.parseInt(catalog.data.size ?? "0", 10) * 1024, 0); return <section className="catalog-usage"><div><span>Package</span><strong>Free</strong></div><div className="catalog-usage-track"><i style={{ width: `${Math.max(.5, Math.min(100, bytes / (500 * 1024 * 1024) * 100))}%` }}/></div><p><b>{Math.max(4, Math.ceil(bytes / 1024))}KB</b> of 500MB space used</p><table><tbody><tr><td>Catalogs</td><td>{Math.max(4, Math.ceil(bytes / 1024))}KB</td></tr></tbody></table></section>; }
function Footer() { return <footer className="catalog-footer">© Braze 2026 <span>Privacy preferences</span><span>Status</span><span>Terms</span><span>Privacy</span></footer>; }

function ItemsTable({ fields, items, open, editable, edit }: { fields: CatalogField[]; items: Item[]; open: (item: Item) => void; editable: boolean; edit: (item: Item) => void }) { return <div className="catalog-scroll"><table className="catalog-grid catalog-items"><thead><tr><th/><th>id</th>{fields.map(field => <th key={field.name}>{field.name}</th>)}{editable && <th/>}</tr></thead><tbody>{items.map(item => <tr key={item.id}><td><button className="catalog-eye" onClick={() => open(item)}><Eye size={17}/></button></td><td>{item.id}</td>{fields.map(field => <td key={field.name}>{display(item.fields[field.name] ?? (field.name === "name" ? item.name : undefined))}</td>)}{editable && <td><button className="catalog-eye" onClick={() => edit(item)}><Pencil size={15}/></button></td>}</tr>)}{!items.length && <tr><td className="catalog-empty" colSpan={fields.length + 3}>No results found</td></tr>}</tbody></table></div>; }
function SelectionsTable({ locale, selections, open, editable, edit, remove }: { locale: Locale; selections: Selection[]; open: (selection: Selection) => void; editable: boolean; edit: (selection: Selection) => void; remove: (selection: Selection) => void }) { return <div className="catalog-scroll"><table className="catalog-grid"><thead><tr><th>Name</th><th>Description</th><th>Filters</th><th>Results limit</th><th>Last updated</th>{editable && <th/>}</tr></thead><tbody>{selections.map(selection => <tr key={selection.name}><td><button className="catalog-link" onClick={() => open(selection)}>{selection.name}</button></td><td>{selection.description}</td><td>{selection.filters.length}</td><td>{selection.resultLimit}</td><td>{date(locale, selection.updatedAt)}</td>{editable && <td><div className="catalog-row-actions"><button onClick={() => edit(selection)}><Pencil size={14}/></button><button onClick={() => remove(selection)}><Trash2 size={14}/></button></div></td>}</tr>)}</tbody></table></div>; }

function FilterPopover({ fields, apply, clear }: { fields: CatalogField[]; apply: (value: { field: string; operator: FilterOperator; value: string }) => void; clear: () => void }) { const [value, setValue] = useState({ field: "", operator: "equals" as FilterOperator, value: "" }); return <div className="catalog-filter-popover"><label>Filter field<select value={value.field} onChange={event => setValue({ ...value, field: event.target.value })}><option value="">Select a field</option>{fields.map(field => <option key={field.name}>{field.name}</option>)}</select></label><label>Operator<select value={value.operator} onChange={event => setValue({ ...value, operator: event.target.value as FilterOperator })}><option value="equals">Equals</option><option value="not_equals">Does not equal</option><option value="contains">Contains</option><option value="not_contains">Does not contain</option><option value="greater_than">Greater than</option><option value="less_than">Less than</option><option value="exists">Exists</option><option value="not_exists">Does not exist</option></select></label>{!value.operator.endsWith("exists") && <label>Value<input value={value.value} onChange={event => setValue({ ...value, value: event.target.value })}/></label>}<div><button className="primary" disabled={!value.field || (!value.operator.endsWith("exists") && !value.value)} onClick={() => apply(value)}>Apply</button><button className="text-button" onClick={clear}>Clear</button></div></div>; }

function Modal({ title, subtitle, close, children, footer }: { title: string; subtitle?: string; close: () => void; children: React.ReactNode; footer?: React.ReactNode }) { return <div className="catalog-modal-backdrop" role="presentation"><section className="catalog-modal" role="dialog" aria-modal="true" aria-label={title}><header><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button onClick={close}><X size={19}/></button></header><div className="catalog-modal-body">{children}</div>{footer && <footer>{footer}</footer>}</section></div>; }

function CreateCatalogDialog({ method, existingNames, setMethod, close, create }: { locale: Locale; method?: "browser" | "csv"; existingNames: string[]; setMethod: (method: "browser" | "csv") => void; close: () => void; create: (catalog: Catalog, items: Item[], fields: CatalogField[]) => void }) {
  const [name, setName] = useState(""); const [description, setDescription] = useState(""); const [fields, setFields] = useState<CatalogField[]>([{ name: "name", type: "string" }]); const [csv, setCsv] = useState<{ headers: string[]; rows: Record<string, string>[] } | null>(null); const [error, setError] = useState("");
  function finish() {
    if (!/^[A-Za-z0-9_-]{1,250}$/.test(name)) { setError("Use 1–250 letters, numbers, hyphens, or underscores."); return; }
    if (existingNames.some(value => value.toLowerCase() === name.toLowerCase())) { setError("Catalog names must be unique."); return; }
    const nextFields = method === "csv" && csv ? csv.headers.filter(header => header !== "id").map(header => ({ name: header, type: inferType(csv.rows.map(row => row[header])) })) : fields;
    if (method === "csv" && (!csv || !csv.headers.includes("id"))) { setError("The first CSV column must be named id."); return; }
    if (nextFields.some(field => !/^[A-Za-z0-9_-]{1,250}$/.test(field.name)) || new Set(nextFields.map(field => field.name.toLowerCase())).size !== nextFields.length) { setError("Field names must be unique and use only letters, numbers, hyphens, or underscores."); return; }
    const types = Object.fromEntries(nextFields.map(field => [field.name, field.type]));
    const items = (csv?.rows ?? []).map(row => ({ id: row.id, name: row.name || row.id, fields: Object.fromEntries(nextFields.map(field => [field.name, coerce(row[field.name] ?? "", types[field.name])])), updatedAt: now() }));
    const catalog: Catalog = { id: uid("catalog"), name, description, status: "Active", updatedAt: now(), itemCount: items.length, data: { source: method === "csv" ? "CSV upload" : "Braze", size: `${Math.max(1, Math.ceil(JSON.stringify(items).length / 1024))}KB` } };
    create(catalog, items, nextFields);
  }
  if (!method) return <Modal title="Create new catalog" subtitle="Choose how you want to add catalog data." close={close}><div className="catalog-create-choices"><button onClick={() => setMethod("csv")}><FileSpreadsheet size={28}/><b>Upload CSV</b><span>Import fields and items from a UTF-8 CSV file.</span></button><button onClick={() => setMethod("browser")}><Database size={28}/><b>Create in browser</b><span>Define fields and add items directly in Braze.</span></button></div></Modal>;
  return <Modal title={method === "csv" ? "Upload CSV" : "Enter catalog details"} subtitle="Catalog names cannot be changed after creation." close={close} footer={<><button className="secondary" onClick={close}>Cancel</button><button className="primary" onClick={finish}>Process Catalog</button></>}><div className="catalog-form"><label>Name<input value={name} onChange={event => setName(event.target.value)} placeholder="my_catalog"/></label><label>Description <small>Optional</small><textarea value={description} onChange={event => setDescription(event.target.value)}/></label>{method === "csv" ? <label className="catalog-dropzone"><Upload size={26}/><b>{csv ? `${csv.rows.length} items ready` : "Upload CSV"}</b><span>First column must be named id.</span><input type="file" accept=".csv,text/csv" onChange={event => { const file = event.target.files?.[0]; if (file) void file.text().then(text => setCsv(parseCsv(text))); }}/></label> : <FieldRows fields={fields} setFields={setFields}/>} {csv && <CsvPreview csv={csv}/>} {error && <p className="catalog-error">{error}</p>}</div></Modal>;
}

function FieldRows({ fields, setFields, allowRemove = true }: { fields: CatalogField[]; setFields: (fields: CatalogField[]) => void; allowRemove?: boolean }) { return <div className="catalog-field-editor"><h3>Catalog fields</h3><div className="catalog-field-row locked"><input value="id" disabled/><select disabled><option>String</option></select></div>{fields.map((field, index) => <div className="catalog-field-row" key={index}><input value={field.name} placeholder="Field name" onChange={event => setFields(fields.map((value, position) => position === index ? { ...value, name: event.target.value.replace(/[^A-Za-z0-9_-]/g, "") } : value))}/><select value={field.type} onChange={event => setFields(fields.map((value, position) => position === index ? { ...value, type: event.target.value as FieldType } : value))}>{fieldTypes.map(type => <option key={type.value} value={type.value}>{type.label}</option>)}</select>{allowRemove && <button onClick={() => setFields(fields.filter((_, position) => position !== index))}><Trash2 size={15}/></button>}</div>)}<button className="catalog-link" onClick={() => setFields([...fields, { name: "", type: "string" }])}><Plus size={14}/> Add field</button></div>; }
function CsvPreview({ csv }: { csv: { headers: string[]; rows: Record<string, string>[] } }) { return <div className="catalog-csv-preview"><h3>Preview</h3><div><table><thead><tr>{csv.headers.map(header => <th key={header}>{header}</th>)}</tr></thead><tbody>{csv.rows.slice(0, 3).map((row, index) => <tr key={index}>{csv.headers.map(header => <td key={header}>{row[header]}</td>)}</tr>)}</tbody></table></div></div>; }

function FieldsDialog({ existing, close, save }: { existing: CatalogField[]; close: () => void; save: (fields: CatalogField[]) => void }) { const [fields, setFields] = useState<CatalogField[]>([{ name: "", type: "string" }]); const valid = fields.length && fields.every(field => field.name && !existing.some(value => value.name === field.name)) && new Set(fields.map(field => field.name)).size === fields.length; return <Modal title="Add fields" subtitle="Field types cannot be changed after they are added." close={close} footer={<><button className="secondary" onClick={close}>Cancel</button><button className="primary" disabled={!valid} onClick={() => save(fields)}>Add fields</button></>}><FieldRows fields={fields} setFields={setFields}/></Modal>; }

function ItemDialog({ fields, item, close, save }: { fields: CatalogField[]; item?: Item; close: () => void; save: (item: Item, originalId?: string) => void }) { const [id, setId] = useState(item?.id ?? ""); const [values, setValues] = useState<Record<string, string>>(Object.fromEntries(fields.map(field => [field.name, item ? display(item.fields[field.name] ?? (field.name === "name" ? item.name : "")) : ""]))); const [error, setError] = useState(""); function finish() { if (!id.trim()) { setError("Item ID is required."); return; } const converted = Object.fromEntries(fields.map(field => [field.name, coerce(values[field.name] ?? "", field.type)])); save({ id: id.trim(), name: String(converted.name ?? id), fields: converted, updatedAt: now() }, item?.id); } return <Modal title={item ? "Edit item" : "Add item"} subtitle="Enter values based on the catalog field types." close={close} footer={<><button className="secondary" onClick={close}>Cancel</button><button className="primary" onClick={finish}>{item ? "Save Item" : "Save Item"}</button></>}><div className="catalog-form"><label>id<input value={id} disabled={Boolean(item)} onChange={event => setId(event.target.value)}/></label>{fields.map(field => <label key={field.name}>{field.name}<small>{fieldTypes.find(value => value.value === field.type)?.label}</small>{field.type === "boolean" ? <select value={values[field.name]} onChange={event => setValues({ ...values, [field.name]: event.target.value })}><option value="">—</option><option value="true">true</option><option value="false">false</option></select> : <input value={values[field.name] ?? ""} onChange={event => setValues({ ...values, [field.name]: event.target.value })}/>}</label>)}{error && <p className="catalog-error">{error}</p>}</div></Modal>; }

function ItemDrawer({ item, fields, editable, close, edit, remove }: { item: Item; fields: CatalogField[]; editable: boolean; close: () => void; edit: () => void; remove: () => void }) { return <aside className="catalog-item-drawer"><header><h2>View Item</h2><button onClick={close}><X size={18}/></button></header><dl><div><dt>id</dt><dd>{item.id}</dd></div>{fields.map(field => <div key={field.name}><dt>{field.name}</dt><dd>{display(item.fields[field.name])}</dd></div>)}</dl>{editable && <footer className="catalog-drawer-actions"><button className="secondary danger" onClick={remove}><Trash2 size={15}/> Delete</button><button className="primary" onClick={edit}><Pencil size={15}/> Edit item</button></footer>}</aside>; }

function SelectionDialog({ catalogId, fields, initial, close, save }: { catalogId: string; fields: CatalogField[]; initial?: Selection; close: () => void; save: (selection: Selection, originalName?: string) => void }) { const [name, setName] = useState(initial?.name ?? ""); const [description, setDescription] = useState(initial?.description ?? ""); const [filters, setFilters] = useState<Selection["filters"]>(initial?.filters ?? [{ field: "", operator: "equals", value: "" }]); const [randomSort, setRandomSort] = useState(initial?.randomSort ?? true); const [sortField, setSortField] = useState(initial?.sortField ?? ""); const [sortDirection, setSortDirection] = useState<"ascending" | "descending">(initial?.sortDirection ?? "ascending"); const [resultLimit, setResultLimit] = useState(initial?.resultLimit ?? 3); const valid = /^[A-Za-z0-9_-]{1,250}$/.test(name) && filters.every(filter => filter.field && (filter.operator.endsWith("exists") || filter.value)); function finish() { save({ catalogId, name, description, filters, randomSort, sortField: randomSort ? "" : sortField, sortDirection, resultLimit: Math.max(1, Math.min(50, resultLimit)), updatedAt: now() }, initial?.name); } return <Modal title={initial ? "Edit selection" : "Create selection"} subtitle="Selections personalize catalog results for each user." close={close} footer={<><button className="secondary" onClick={close}>Cancel</button><button className="primary" disabled={!valid} onClick={finish}>{initial ? "Save changes" : "Create Selection"}</button></>}><div className="catalog-form"><label>Name<input value={name} disabled={Boolean(initial)} onChange={event => setName(event.target.value.replace(/[^A-Za-z0-9_-]/g, ""))}/></label><label>Description <small>Optional</small><textarea value={description} onChange={event => setDescription(event.target.value)}/></label><h3>Filter settings</h3>{filters.map((filter, index) => <div className="selection-filter-editor" key={index}><select value={filter.field} onChange={event => setFilters(filters.map((value, position) => position === index ? { ...value, field: event.target.value } : value))}><option value="">Filter field</option>{fields.map(field => <option key={field.name}>{field.name}</option>)}</select><select value={filter.operator} onChange={event => setFilters(filters.map((value, position) => position === index ? { ...value, operator: event.target.value as FilterOperator } : value))}><option value="equals">Equals</option><option value="not_equals">Does not equal</option><option value="contains">Contains</option><option value="not_contains">Does not contain</option><option value="greater_than">Greater than</option><option value="less_than">Less than</option><option value="exists">Exists</option><option value="not_exists">Does not exist</option></select>{!filter.operator.endsWith("exists") && <input value={filter.value} placeholder="Value or Liquid" onChange={event => setFilters(filters.map((value, position) => position === index ? { ...value, value: event.target.value } : value))}/>}<button disabled={filters.length === 1} onClick={() => setFilters(filters.filter((_, position) => position !== index))}><X size={15}/></button></div>)}<button className="catalog-link" disabled={filters.length >= 10} onClick={() => setFilters([...filters, { field: "", operator: "equals", value: "" }])}><Plus size={14}/> Add filter</button><h3>Sort type</h3><label className="catalog-checkbox"><input type="checkbox" checked={randomSort} onChange={event => setRandomSort(event.target.checked)}/> Randomize sort order</label>{!randomSort && <div className="catalog-two-columns"><label>Sort field<select value={sortField} onChange={event => setSortField(event.target.value)}><option value="">Select a field</option>{fields.map(field => <option key={field.name}>{field.name}</option>)}</select></label><label>Sort order<select value={sortDirection} onChange={event => setSortDirection(event.target.value as "ascending" | "descending")}><option value="ascending">Ascending</option><option value="descending">Descending</option></select></label></div>}<label>Results limit<input type="number" min="1" max="50" value={resultLimit} onChange={event => setResultLimit(Number(event.target.value))}/><small>You can include up to 50 catalog items.</small></label></div></Modal>; }

function CsvUpdateDialog({ fields, items, close, apply }: { fields: CatalogField[]; items: Item[]; close: () => void; apply: (mode: "merge" | "replace" | "delete", items: Item[]) => void }) { const [mode, setMode] = useState<"merge" | "replace" | "delete">("merge"); const [csv, setCsv] = useState<{ headers: string[]; rows: Record<string, string>[] } | null>(null); const converted = csv?.rows.map(row => ({ id: row.id, name: row.name || row.id, fields: Object.fromEntries(fields.map(field => [field.name, coerce(row[field.name] ?? "", field.type)])), updatedAt: now() })) ?? []; return <Modal title="Upload CSV" subtitle="Add, update, replace, or delete catalog items." close={close} footer={<><button className="secondary" onClick={close}>Cancel</button><button className="primary" disabled={!csv?.headers.includes("id")} onClick={() => apply(mode, converted)}>Process CSV</button></>}><div className="catalog-form"><label>Import action<select value={mode} onChange={event => setMode(event.target.value as typeof mode)}><option value="merge">Add or update items</option><option value="replace">Replace all items</option><option value="delete">Delete matching item IDs</option></select></label><label className="catalog-dropzone"><Upload size={26}/><b>{csv ? `${converted.length} of ${items.length} items` : "Choose CSV file"}</b><span>The file must contain an id column.</span><input type="file" accept=".csv,text/csv" onChange={event => { const file = event.target.files?.[0]; if (file) void file.text().then(text => setCsv(parseCsv(text))); }}/></label>{csv && <CsvPreview csv={csv}/>}</div></Modal>; }

function SettingsPanel({ settings, fields, editable, save }: { settings: CatalogSettings; fields: CatalogField[]; editable: boolean; save: (settings: CatalogSettings) => void }) { const [draft, setDraft] = useState(settings); return <section className="catalog-settings"><h1>Settings{!editable && <ViewOnly/>}</h1><p>Configure the settings for Canvases and campaigns connected to this catalog. <a href="https://www.braze.com/docs/user_guide/data/activation/catalogs/" target="_blank">Read more in documentation.</a></p><div className="catalog-setting-card"><div className="catalog-setting-title"><div><h2>Back in stock</h2><p>Notify subscribed users when inventory becomes available.</p></div><label className="catalog-switch"><input type="checkbox" disabled={!editable} checked={draft.backInStock} onChange={event => setDraft({ ...draft, backInStock: event.target.checked })}/><span/></label></div>{draft.backInStock && <div className="catalog-setting-fields"><label>Custom event for subscriptions<input value={draft.subscriptionEvent} onChange={event => setDraft({ ...draft, subscriptionEvent: event.target.value })}/></label><label>Custom event for unsubscribing <small>Optional</small><input value={draft.unsubscribeEvent} onChange={event => setDraft({ ...draft, unsubscribeEvent: event.target.value })}/></label><label>Item ID event property<input value={draft.itemIdProperty} onChange={event => setDraft({ ...draft, itemIdProperty: event.target.value })}/></label><label>Inventory quantity field<select value={draft.inventoryField} onChange={event => setDraft({ ...draft, inventoryField: event.target.value })}><option value="">Select a number field</option>{fields.filter(field => field.type === "number").map(field => <option key={field.name}>{field.name}</option>)}</select></label></div>}</div><div className="catalog-setting-card"><div className="catalog-setting-title"><div><h2>Price drop</h2><p>Trigger notifications when a numeric price field decreases.</p></div><label className="catalog-switch"><input type="checkbox" disabled={!editable} checked={draft.priceDrop} onChange={event => setDraft({ ...draft, priceDrop: event.target.checked })}/><span/></label></div>{draft.priceDrop && <div className="catalog-setting-fields"><label>Price field<select value={draft.priceField} onChange={event => setDraft({ ...draft, priceField: event.target.value })}><option value="">Select a number field</option>{fields.filter(field => field.type === "number").map(field => <option key={field.name}>{field.name}</option>)}</select></label></div>}</div><div className="catalog-setting-card"><h2>Notification rules</h2><label><input type="radio" disabled={!editable} checked={draft.notifyMode === "all"} onChange={() => setDraft({ ...draft, notifyMode: "all" })}/> Notify all subscribed users</label><label><input type="radio" disabled={!editable} checked={draft.notifyMode === "rate"} onChange={() => setDraft({ ...draft, notifyMode: "rate" })}/> Notify a certain number of users per 10 minutes</label>{draft.notifyMode === "rate" && <input type="number" min="1" value={draft.rate} onChange={event => setDraft({ ...draft, rate: Number(event.target.value) })}/>}</div><div className="catalog-setting-card"><h2>Subscriptions</h2><p>Users who subscribed to catalog notifications. Subscriptions expire after messages are sent, after 90 days, or after an unsubscribe event.</p><p>Active subscriptions: <b>0 / 100,000,000</b></p></div>{editable && <footer className="catalog-settings-footer"><button className="primary" onClick={() => save(draft)}>Save changes</button></footer>}</section>; }

function SelectionView({ locale, catalog, selection, items, editable, loading, onBack, onEdit, dialog, closeDialog, saveSelection }: { locale: Locale; catalog: Catalog; selection?: Selection; items: Item[]; editable: boolean; loading: boolean; onBack: () => void; onEdit: () => void; dialog: Dialog; closeDialog: () => void; saveSelection: (selection: Selection, originalName: string) => void }) {
  const [preview, setPreview] = useState<Item[] | null>(null);
  const fields = (catalog.data.fields ?? []).map(name => ({ name, type: catalog.data.fieldTypes?.[name] ?? "string" as FieldType }));
  if (!selection) return <div className="braze-catalog"><main className="catalog-main"><h1>{loading ? "Loading selection…" : "Selection not found"}</h1><button className="catalog-link" onClick={onBack}>Back to Selections</button></main></div>;
  const current = selection;
  function generate() {
    let result = items.filter(item => current.filters.every(filter => matches(item, filter)));
    if (current.randomSort) result = [...result].sort((left, right) => left.id.localeCompare(right.id));
    else if (current.sortField) result = [...result].sort((left, right) => String(left.fields[current.sortField] ?? "").localeCompare(String(right.fields[current.sortField] ?? "")) * (current.sortDirection === "descending" ? -1 : 1));
    setPreview(result.slice(0, current.resultLimit));
  }
  return <div className="braze-catalog"><nav className="catalog-workspace-tabs"><button onClick={onBack}>Catalogs</button><button onClick={onBack}>{catalog.name}</button><button className="selected">{current.name}<X size={14} onClick={onBack}/></button></nav><main className="catalog-main selection-main"><header className="selection-heading"><div><h1>View selection{!editable && <ViewOnly/>}</h1><p>Selections are subsets of a catalog that personalize messages for each user.</p></div>{editable && <button className="primary" onClick={onEdit}><Pencil size={15}/> Edit selection</button>}</header><section className="selection-details"><label>Name<input value={current.name} disabled/></label><label>Description<textarea value={current.description} disabled/></label><h2>Filter settings</h2>{current.filters.map((filter, index) => <div className="selection-filter" key={index}><span>{filter.field}</span><span>{filter.operator.replaceAll("_", " ")}</span><span>{filter.value || "—"}</span></div>)}<h2>Sorting type</h2><p>{current.randomSort ? "Random sort" : `${current.sortField} · ${current.sortDirection}`}</p><label>Results limit<input value={current.resultLimit} disabled/><small>You can include up to 50 catalog items in a selection.</small></label></section><section className="selection-user-preview"><h2>Preview for user</h2><p>Preview what this selection returns for a random user.</p><div className="selection-user-controls"><button className="secondary" onClick={generate}>Get random user</button><button className="primary" onClick={generate}>Generate preview</button></div>{preview && <><h3>Preview results</h3><ItemsTable fields={fields} items={preview} open={() => {}} editable={false} edit={() => {}}/></>}</section><footer className="selection-footer"><button className="primary" onClick={onBack}>Close</button></footer></main>{dialog?.kind === "selection" && <SelectionDialog catalogId={catalog.id} fields={[{ name: "id", type: "string" }, ...fields]} initial={current} close={closeDialog} save={(next, originalName) => saveSelection(next, originalName ?? current.name)}/>}</div>;
}

export function RecommendationStudio({ locale, id, notify }: { locale: Locale; id: string; notify: (message: string) => void }) {
  const router = useRouter(); const [recommendation, setRecommendation] = useState<Recommendation | null>(null); const [catalogs, setCatalogs] = useState<Catalog[]>([]); const [selections, setSelections] = useState<Selection[]>([]); const [step, setStep] = useState(0);
  useEffect(() => { void (async () => {
    const [recommendationResponse, catalogsResponse] = await Promise.all([fetch(`/api/recommendations/${id}`), fetch("/api/catalogs")]);
    if (recommendationResponse.ok) setRecommendation(await recommendationResponse.json()); else notify("Recommendation not found.");
    const apiCatalogs = catalogsResponse.ok ? (await catalogsResponse.json()).data.filter((catalog: Catalog) => catalog.id !== "catalog_featured") as Catalog[] : [];
    const browserCatalogs = Object.values(loadLocal().records).map(record => ({ ...record.catalog, itemCount: record.items.length }));
    const merged = new Map(apiCatalogs.map(catalog => [catalog.name.toLowerCase(), catalog])); browserCatalogs.forEach(catalog => merged.set(catalog.name.toLowerCase(), catalog)); setCatalogs([...merged.values()]);
  })(); }, [id, notify]);
  useEffect(() => { const catalogId = recommendation?.data.catalogId; if (!catalogId) { setSelections([]); return; } const localSelections = loadLocal().records[catalogId]?.selections; if (localSelections) { setSelections(localSelections); return; } void fetch(`/api/catalogs/${catalogId}/selections`).then(response => response.ok ? response.json() : { data: [] }).then(result => setSelections(result.data)); }, [recommendation?.data.catalogId]);
  function update(patch: Partial<Recommendation>) { setRecommendation(current => current ? { ...current, ...patch, data: { ...current.data, ...patch.data } } : current); }
  async function save(nextStep?: number) { if (!recommendation) return; const response = await fetch(`/api/recommendations/${id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name: recommendation.name, description: recommendation.description, data: recommendation.data }) }); if (!response.ok) { notify("Could not save recommendation."); return; } setRecommendation(await response.json()); if (nextStep != null) setStep(nextStep); else notify("Recommendation saved."); }
  if (!recommendation) return <div className="braze-catalog"><main className="catalog-main"><p>Loading recommendation…</p></main></div>;
  const canContinue = step === 0 ? Boolean(recommendation.name.trim()) : step === 1 ? Boolean(recommendation.data.recommendationType && recommendation.data.catalogId) : Boolean(recommendation.data.trackingType && recommendation.data.propertyName);
  return <div className="braze-catalog recommendation-workspace"><nav className="catalog-workspace-tabs"><button onClick={() => router.push(listUrl(locale))}>Catalogs</button><button className="selected">{recommendation.name}<X size={14} onClick={() => router.push(listUrl(locale))}/></button></nav><main className="catalog-main recommendation-main"><div className="recommendation-free">Recommendations are available in your Free plan. <a href="https://www.braze.com/docs/user_guide/brazeai/recommendations/" target="_blank">Learn more</a></div><header className="recommendation-heading"><h1>Create recommendation</h1><span>Step {step + 1} of 3</span></header><ol className="recommendation-steps"><li className={step === 0 ? "active" : "complete"}>1 <span>Recommendation details</span></li><li className={step === 1 ? "active" : step > 1 ? "complete" : ""}>2 <span>Define your recommendation</span></li><li className={step === 2 ? "active" : ""}>3 <span>Track your recommendation</span></li></ol>{step === 0 && <section className="recommendation-card"><h2>Recommendation details</h2><p>Give your recommendation a name and description.</p><label>Name<input value={recommendation.name} onChange={event => update({ name: event.target.value })}/></label><label>Description <small>Optional</small><textarea value={recommendation.description} onChange={event => update({ description: event.target.value })}/></label></section>}{step === 1 && <section className="recommendation-card"><h2>Define your recommendation</h2><p>Select the catalog and recommendation type that define your personalized content.</p><label>Type<select value={recommendation.data.recommendationType ?? ""} onChange={event => update({ data: { recommendationType: event.target.value } })}><option value="">Select a type</option><option value="personalized">Personalized</option><option value="most_popular">Most popular</option><option value="recently_viewed">Recently viewed</option></select></label><label>Catalog<select value={recommendation.data.catalogId ?? ""} onChange={event => update({ data: { catalogId: event.target.value, selectionName: "" } })}><option value="">Select a catalog</option>{catalogs.map(catalog => <option key={catalog.id} value={catalog.id}>{catalog.name}</option>)}</select></label><label>Selection <small>Optional</small><select value={recommendation.data.selectionName ?? ""} disabled={!recommendation.data.catalogId} onChange={event => update({ data: { selectionName: event.target.value } })}><option value="">No selection</option>{selections.map(selection => <option key={selection.name}>{selection.name}</option>)}</select></label></section>}{step === 2 && <section className="recommendation-card"><h2>Track your recommendation</h2><p>Choose the behavior that determines the order of recommended catalog items.</p>{[["purchase_object", "Purchase object", "Use purchase object properties to track orders."], ["purchase_event", "Purchase event", "Use purchase events to track orders."], ["custom_event", "Custom event", "Use a custom event and property to track orders."]].map(([value, title, description]) => <label className="recommendation-radio" key={value}><input type="radio" name="tracking" value={value} checked={recommendation.data.trackingType === value} onChange={() => update({ data: { trackingType: value } })}/><span><b>{title}</b><small>{description}</small></span></label>)}<label>Property name<input value={recommendation.data.propertyName ?? ""} onChange={event => update({ data: { propertyName: event.target.value } })}/><small>Match this property to the catalog item ID used in your tracking event.</small></label></section>}<footer className="recommendation-footer"><button className="secondary" disabled={step === 0} onClick={() => setStep(step - 1)}>Back</button><span/><button className="primary" disabled={!canContinue} onClick={() => void save(step < 2 ? step + 1 : undefined)}>{step < 2 ? "Continue" : "Save recommendation"}</button></footer></main></div>;
}

function ConfirmDialog({ title, body, confirmLabel, close, confirm }: { title: string; body: string; confirmLabel: string; close: () => void; confirm: () => void }) { return <Modal title={title} close={close} footer={<><button className="secondary" onClick={close}>Cancel</button><button className="primary danger-button" onClick={confirm}>{confirmLabel}</button></>}><p>{body}</p><p className="catalog-warning">This action cannot be undone.</p></Modal>; }
